if (ship.shield) {
  // shield absorbs meteor
  sounds.explosion.play();
  ship.shield = false; // shield consumed
  meteors.splice(i, 1);
} else {
  // ship destroyed
  sounds.explosion.play();
  gameOver = true;
}

